package com.example.starter.incident;

/**
 * 指令计划状态机：
 * RUNNING（执行中，含尚未执行任何步骤）→ COMPLETED（全部步骤 APPLIED）；
 * RUNNING 或 COMPLETED 可取消进入 COMPENSATING；COMPENSATING 逆序补偿完成后 → CANCELLED。
 * COMPENSATING/CANCELLED 为补偿阶段：COMPENSATING 阻止事件进入 RESOLVED，
 * 仅当全部计划 COMPLETED 或 CANCELLED 时事件才可解决。
 */
public enum PlanStatus {

    /** 执行中：至少还有步骤未 APPLIED（含一步未执行）。 */
    RUNNING,

    /** 全部步骤已 APPLIED。 */
    COMPLETED,

    /** 已取消，正在按已执行步骤逆序逐项补偿；未执行步骤不再执行。 */
    COMPENSATING,

    /** 全部已执行步骤补偿完成，终态。 */
    CANCELLED
}

package com.example.starter.incident;

/**
 * 计划步骤状态机：PENDING → APPLIED → COMPENSATED。
 * PENDING 未执行；APPLIED 已生效（原子记录一次，重复执行旧成功步骤不重复记效果）；
 * COMPENSATED 已补偿。进入 COMPENSATING 后 PENDING 步骤永久不再执行。
 */
public enum PlanStepStatus {

    /** 未执行。 */
    PENDING,

    /** 已生效：显式执行当前下一步时原子置为该状态。 */
    APPLIED,

    /** 已补偿：补偿成功后由 APPLIED 转入，终态。 */
    COMPENSATED
}

package com.example.starter.incident;

/**
 * 单次补偿尝试结果。失败仅保存失败诊断、不改变步骤 APPLIED 状态，
 * 允许用新 commandKey 重试；成功保存补偿证据并将步骤置为 COMPENSATED。
 */
public enum CompensationStatus {

    /** 补偿成功：步骤转 COMPENSATED，evidence 非空。 */
    SUCCEEDED,

    /** 补偿失败：仅写入 failureDiagnostic，步骤保持 APPLIED。 */
    FAILED
}

